import{_ as t,o as a,c as h,a3 as o}from"./chunks/framework.DX_KL3e0.js";const c="/help/screenshots/quan-tri/co-cau-to-chuc.png",m=JSON.parse('{"title":"Cơ cấu tổ chức","description":"","frontmatter":{},"headers":[],"relativePath":"quan-tri/co-cau-to-chuc.md","filePath":"quan-tri/co-cau-to-chuc.md","lastUpdated":1781595364000}'),r={name:"quan-tri/co-cau-to-chuc.md"};function i(g,n,e,s,l,u){return a(),h("div",null,[...n[0]||(n[0]=[o('<h1 id="co-cau-to-chuc" tabindex="-1">Cơ cấu tổ chức <a class="header-anchor" href="#co-cau-to-chuc" aria-label="Permalink to &quot;Cơ cấu tổ chức&quot;">​</a></h1><p>Trang <strong>Sơ Đồ Tổ Chức</strong> quản lý cấu trúc doanh nghiệp theo cây 3 cấp: <strong>Công ty → Phòng ban → Bộ phận</strong>, kèm chức danh, vị trí và người phụ trách.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/organization</code> (nhóm <em>Điều Hướng</em>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin tạo/sửa; Quản lý chỉ <code>Xem</code>.</li><li><strong>Cấu trúc:</strong> cây Công ty › Phòng ban › Bộ phận, hiển thị quân số và nhân sự.</li></ul></div><h2 id="cay-to-chuc" tabindex="-1">Cây tổ chức <a class="header-anchor" href="#cay-to-chuc" aria-label="Permalink to &quot;Cây tổ chức&quot;">​</a></h2><p><img src="'+c+'" alt="Trang Cơ cấu tổ chức"></p><p>Bấm biểu tượng mũi tên (›) trên mỗi dòng để bung <strong>phòng ban · bộ phận · nhân sự</strong>. Số bên cạnh tên là <strong>quân số</strong>; huy hiệu người phụ trách hiển thị trưởng đơn vị.</p><h2 id="them-sua-xoa" tabindex="-1">Thêm / sửa / xóa <a class="header-anchor" href="#them-sua-xoa" aria-label="Permalink to &quot;Thêm / sửa / xóa&quot;">​</a></h2><p>Mỗi dòng có 3 nút thao tác: <strong>➕ thêm cấp con</strong>, <strong>✏️ sửa</strong>, <strong>🗑️ xóa</strong>.</p><h3 id="them-cong-ty" tabindex="-1">Thêm công ty <a class="header-anchor" href="#them-cong-ty" aria-label="Permalink to &quot;Thêm công ty&quot;">​</a></h3><ol><li>Nhấn <strong>Thêm Công Ty</strong> ở góc phải header.</li><li>Nhập <strong>Tên</strong> (vd: <em>FADO Group</em>), mô tả, mã số thuế, địa chỉ, website...</li><li>Nhấn <strong>Lưu</strong>.</li></ol><h3 id="them-phong-ban" tabindex="-1">Thêm phòng ban <a class="header-anchor" href="#them-phong-ban" aria-label="Permalink to &quot;Thêm phòng ban&quot;">​</a></h3><ol><li>Bấm nút <strong>➕</strong> trên dòng công ty.</li><li>Nhập <strong>Tên phòng ban</strong> (vd: <em>Phòng Kế Toán</em>), mã, mô tả, người phụ trách.</li><li>Nhấn <strong>Lưu</strong>.</li></ol><h3 id="them-bo-phan" tabindex="-1">Thêm bộ phận <a class="header-anchor" href="#them-bo-phan" aria-label="Permalink to &quot;Thêm bộ phận&quot;">​</a></h3><ol><li>Bung phòng ban, bấm nút <strong>➕</strong> trên dòng phòng ban.</li><li>Nhập <strong>Tên bộ phận</strong> (vd: <em>Kế Toán Tổng Hợp</em>), mô tả.</li><li>Nhấn <strong>Lưu</strong>.</li></ol><h2 id="chuc-danh-vi-tri" tabindex="-1">Chức danh &amp; vị trí <a class="header-anchor" href="#chuc-danh-vi-tri" aria-label="Permalink to &quot;Chức danh &amp; vị trí&quot;">​</a></h2><p>Ngoài cây tổ chức, module còn quản lý:</p><ul><li><strong>Chức danh công việc</strong> (<code>/organization/job-titles</code>) — danh mục chức danh dùng chung.</li><li><strong>Vị trí / chức vụ</strong> (<code>/organization/positions</code>) — vị trí theo từng công ty, có thể kèm dải lương.</li><li><strong>Thẻ tổ chức</strong> (<code>/organization/tags</code>) — gắn nhãn cho công ty/phòng ban.</li></ul><p>Các giá trị này được dùng lại khi gán cho người dùng (xem <a href="/help/quan-tri/nguoi-dung.html">Người dùng &amp; phân quyền</a>).</p><div class="warning custom-block"><p class="custom-block-title">Xóa cẩn trọng</p><p>Xóa một công ty/phòng ban/bộ phận sẽ ảnh hưởng tới nhân sự đang gắn vào đó. Mặc định <strong>Admin không có quyền Xóa</strong> — thao tác này dành cho Super Admin.</p></div><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/to-chuc.html">Tổ chức (cẩm nang)</a> · <a href="/help/quan-tri/nguoi-dung.html">Người dùng &amp; phân quyền</a></p>',21)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
